// AUTOGEGENEREERD door maak_assets_ts.py — niet met de hand bewerken.
// Bron: tapas_slider.css + tapas_kompas.css uit de gemeten Kompas-generator,
// met Noto Sans-subsets als data-URI zodat Chromium exact dezelfde
// fontmetriek gebruikt als WeasyPrint.
export const KOMPAS_CSS: string = `@font-face{font-family:'Noto Sans';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:italic;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:normal;font-weight:500;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:italic;font-weight:500;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:italic;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:italic;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'Noto Sans';font-style:normal;font-weight:800;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
/* ============================================================================
   tapas_slider.css — SINGLE SOURCE OF TRUTH voor de visuele stijl van
   het T4P Business Kompas / Business Profiel (A4, Noto Sans).

   Alle waarden hieronder zijn GEMETEN uit de standaardreferentie
   T4P-Business-Kompas-Marc-Debisschop-05062026 (32 pagina's, sectie 06
   "Bronstellingen — Drivers"), met PyMuPDF: paginaformaat 595,30 x 841,90 pt,
   producer WeasyPrint 69.0, lettertypen Noto Sans met DejaVu Sans als terugval.

   RENDERER: WeasyPrint 69.0. Niet Chromium. De referentie draagt een
   doorlopende voettekst met automatische paginanummering; die vraagt CSS
   margin boxes (@bottom-left / @bottom-right) en counter(page), en die kent
   Chromium's print-naar-pdf niet.

   EENHEID: pt, gelijk aan de meeteenheid van de referentie. Meng hier geen px
   in: de vorige versie noteerde referentie-puntwaarden als px, waardoor alle
   typografie 25% te klein uitviel.
   ========================================================================== */

/* ---------------------------------------------------------------- fonts ---
   Noto Sans staat als systeemfont in de renderomgeving en is exact wat de
   referentie insluit (Noto-Sans, -Semi-Bold, -Bold, -Ultra-Bold, -Italic).
   DejaVu Sans is de terugval voor tekens die Noto mist, zoals het echte
   minteken U+2212 in de nettoscores.                                       */

/* --------------------------------------------------------------- tokens --- */
:root{
  /* dragende kleuren, gemeten uit de standaardreferentie */
  --teal:#1b5e5a;          /* hoofdstuktitels, tabelheader, bandlabels       */
  --teal-rule:#1b5e5a;     /* filet onder de titel, accentbalk mint-band     */
  --teal-deep:#134542;     /* citaten, positieve nettowaarden                */
  --ochre:#b8860b;         /* hoofdstuknummers, TOC-nummers, aanhalingstekens*/
  --rust:#a0522d;          /* accentbalk risicoband, negatieve energie       */
  --rust-deep:#a0522d;     /* labeltekst risicoband, negatieve saldowaarde   */
  --green:#437a22;         /* positieve energie, actielabel                  */
  --green-bar:#437a22;     /* accentbalk actieband                          */
  --ink:#23211d;           /* broodtekst, tabelwaarden                      */
  --ink-soft:#4a463f;      /* verhalende tekst, subtitels                   */
  --ink-faint:#6e6a62;     /* runhead, paginanummer, veldlabels             */
  --line:#d9d6cf;          /* kaartrand, tabelrasters, TOC-filet            */
  --line-warm:#e7e3db;     /* lege batterijcel, zebra-rand                  */
  --canvas:#ffffff;        /* het blad zelf — de referentie kent geen kaart  */
  --card:#ffffff;
  --paper:#fcfbf8;         /* zebrarij, zachte vlakvulling                  */
  --mint:#eef2f0;          /* kernboodschap / professionele betekenis        */
  --sand:#f5e6dd;          /* bewaking of risico                            */
  --leaf:#eef3ee;          /* actie of ontwerpimplicatie                     */
  --cream:#fcfbf8;         /* zebrarij in tabellen                          */

  /* maten, gemeten */
  --card-pad:0pt;          /* de referentie zet geen kaart op het blad       */
  --content-w:491.3pt;     /* x 52,0 -> 543,3 op een binnenpagina            */
}

/* ----------------------------------------------------------- paginabasis ---
   Marges gemeten: binnenpagina links/rechts 52,0 pt, tekstbovenkant 58,2 pt,
   voettekst-bovenkant 793,9 pt. De omslag heeft een ruimere marge: 64,0 pt.  */
@page{
  size:A4;
  margin:52pt 52pt 48pt 52pt;

  @bottom-left{
    content:"TaPasCity · T4P Business Profiel · confidential";
    font-family:"Noto Sans","DejaVu Sans",sans-serif;
    font-size:7.5pt; font-weight:700; color:#1b5e5a;
    vertical-align:top; padding-top:0pt;
  }
  @bottom-right{
    content:counter(page);
    font-family:"Noto Sans","DejaVu Sans",sans-serif;
    font-size:7.5pt; font-weight:600; color:#6e6a62;
    vertical-align:top; padding-top:0pt;
  }
}

/* De omslag draagt geen voettekst en geen paginanummer, en heeft een
   ruimere marge. Gemeten: inhoud x 64,0 -> 531,3.                          */
@page omslag{
  margin:64pt;
  @bottom-left{ content:none; }
  @bottom-right{ content:none; }
}

*{ box-sizing:border-box; }

html,body{
  margin:0; padding:0;
  background:transparent;
  font-family:"Noto Sans","DejaVu Sans",sans-serif;
  font-weight:400;
  color:var(--ink);
  font-variant-ligatures:none;
}

/* Eén .sheet = één A4-pagina. De inhoud staat rechtstreeks op het blad
   binnen de @page-marges; er is geen zwevende kaart. */
.sheet{
  position:relative;
  break-after:page;
  page-break-after:always;
}
.sheet:last-child{ page-break-after:auto; break-after:auto; }
.sheet.omslag{ page:omslag; }
/* Gemeten: op de omslag staat de vertrouwelijkheidsregel onderaan het
   inhoudsvlak (filet y 744,9 / tekst y 767,0 bij een ondermarge van 64pt).
   Inhoudshoogte = 841,89 - 64 - 64 = 713,89pt. */
.sheet.omslag > .card{ position:relative; height:713.89pt; }
.sheet.omslag .cover-conf{ position:absolute; left:0; right:0; bottom:0;
                           margin-top:0; }

.card{
  position:relative;
  width:100%;
  background:transparent;
  border:0;
  padding:0;
}

/* Kopregel rechtsboven, gemeten: "M A R C · D E B I S S C H O P", 6,8pt
   semi-bold, rechts uitgelijnd op x 543,3, bovenkant y 46,7. De kopregel staat
   BUITEN de tekststroom: in de referentie staat het hoofdstuknummer (y 45,2)
   op dezelfde hoogte, dus de kopregel neemt geen verticale ruimte in. */
.runhead{
  position:absolute; top:-6.1pt; left:0; right:0;
  text-align:right;
  font-size:6.8pt; font-weight:600;
  letter-spacing:.14em; text-transform:uppercase;
  color:var(--ink-faint);
  margin:0;
}

/* compacte hoofdstukken: alle verticale ritmes krapper */

/* --------------------------------------------------------- hoofdstukkop ---
   Gemeten: nummer 42,0pt Bold #b8860b, titel 25,0pt Ultra-Bold #1b5e5a.    */
.chap-head{ display:flex; align-items:flex-start; gap:16.0pt; margin-top:0.8pt; }
.chap-num{ font-size:42pt; font-weight:700; color:var(--ochre); line-height:1; }
.chap-title{ font-size:25pt; font-weight:800; color:var(--teal);
             line-height:25pt; position:relative; top:1.6pt;
             flex:1 1 auto; min-width:0; padding-bottom:6.3pt; }
.chap-rule{ height:2pt; background:var(--teal-rule); margin:5.9pt 0 0; }
.chap-sub{ font-size:10.5pt; font-style:italic; color:var(--ink-faint); margin:7.7pt 0 10.5pt; }

/* Gemeten broodtekst: 9,6pt Noto Sans #4a463f. */
p{ font-size:9.6pt; line-height:1.5; color:var(--ink-soft); margin:6pt 0; }
.lead{ font-size:10pt; font-weight:700; color:var(--ink); margin:9pt 0 6pt; }
.intro-tekst{ font-size:9.6pt; line-height:1.5; color:var(--ink-soft); margin:6pt 0 9pt; }
.subhead{ font-size:7.4pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
          color:var(--teal); margin:10.5pt 0 4.5pt; }
b,strong{ font-weight:700; }
i,em{ font-style:italic; }

/* -------------------------------------------------------------- omslag ---
   Alle waarden gemeten op pagina 1 van de standaardreferentie.
   Inhoudsbreedte 467,3 pt (x 64,0 -> 531,3). Geen voettekst, geen
   paginanummer en GEEN inhoudsopgave: de inhoudsopgave is pagina 2.        */
.cover-brand{ padding-top:16.4pt; font-size:22pt; font-weight:800; color:var(--teal);
              line-height:1.1; }
.cover-brand-rule{ height:2.4pt; background:var(--teal); margin:19pt 0 0; }
.cover-eyebrow{ margin-top:116pt; font-size:9pt; font-weight:700; letter-spacing:.42em;
                color:var(--ochre); text-transform:uppercase; }
.cover-title{ font-size:74pt; font-weight:800; color:var(--teal); line-height:.98;
              margin:6.7pt 0 0; letter-spacing:-.01em; }
.cover-claim{ margin:14pt 0 0; font-size:15.5pt; font-style:italic; color:var(--ink-soft);
              line-height:1.3; }
.cover-grid{ display:grid; grid-template-columns:134pt 1fr; row-gap:12.6pt;
             border-top:1pt solid var(--line); margin-top:57.5pt; padding-top:19pt; }
.cover-grid .k{ font-size:7.6pt; font-weight:700; letter-spacing:.19em;
                text-transform:uppercase; color:var(--ink-faint); padding-top:2.2pt; }
.cover-grid .v{ font-size:11.5pt; font-weight:600; color:var(--ink); }
.cover-conf{ border-top:1pt solid var(--line); margin-top:20pt; padding-top:15pt;
             font-size:7.6pt; font-weight:700; letter-spacing:.19em;
             text-transform:uppercase; color:var(--teal); }

/* ---------------------------------------------------------------- TOC ----
   Gemeten op pagina 2: titel 32,0pt Ultra-Bold, filet 2,0pt op y 107–109,
   24 rijen met een vaste rijhoogte van 26,8pt, nummer 15,5pt Bold #b8860b
   op x 52,0 en titel 11,4pt Semi-Bold #23211d op x 98,0.                    */
.toc-title{ font-size:32pt; font-weight:800; color:var(--teal); margin:11.2pt 0 0;
            line-height:1.05; }
.toc-rule{ height:2pt; background:var(--teal-rule); margin:9pt 0 9.9pt; }
.toc-row{ display:flex; align-items:baseline; height:26.8pt;
          border-bottom:1pt solid var(--line); }
.toc-row .num{ font-size:15.5pt; font-weight:700; color:var(--ochre);
               min-width:46pt; line-height:26.8pt; }
.toc-row .ttl{ font-size:11.4pt; font-weight:600; color:var(--ink);
               line-height:26.8pt; position:relative; top:-2.35pt; }
.toc.compact .toc-row{ height:26.8pt; }
.toc.compact .toc-row .num{ font-size:15.5pt; }
.toc.compact .toc-row .ttl{ font-size:11.4pt; }
.readbox{ margin:10pt 0 0; background:var(--mint);
          border-left:5pt solid var(--teal); padding:9.1pt 15pt 8pt; }
.readbox .rb-lbl{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
                  color:var(--teal); margin-bottom:4pt; }
.readbox p{ font-size:12.5pt; margin:4pt 0; }

/* ----------------------------------------------------- lagen (bandjes) --- */
/* Gemeten op de standaardreferentie: vlak over de volle tekstbreedte
   (x 52 -> 543,3), linkerbalk 5pt, tekstinzet x 70 (= 5pt balk + 13pt
   binnenmarge). Label 7,4pt Bold met letterspatiëring, bovenkant 10,5pt onder
   de vlakrand. Broodtekst 9,4pt met een regelafstand van 13,3pt in #4a463f;
   vette accenten in #23211d. Tussenruimte tussen twee vlakken: 8pt. */
.laag{ background:var(--mint); border-left:5pt solid var(--teal-rule);
       padding:10.5pt 16pt 12pt 13pt; margin:4pt 0; break-inside:avoid; }
.laag .l-lbl{ font-size:7.4pt; font-weight:700; letter-spacing:.16em;
              text-transform:uppercase; color:var(--teal); margin-bottom:5.6pt; }
.laag .l-txt{ font-size:9.4pt; line-height:13.3pt; color:var(--ink-soft); }
.laag .l-txt b, .laag .l-txt strong{ color:var(--ink); }
.laag.risico{ background:var(--sand); border-left-color:var(--rust); }
.laag.risico .l-lbl{ color:var(--rust-deep); }
.laag.actie{ background:var(--leaf); border-left-color:var(--green-bar); }
.laag.actie .l-lbl{ color:var(--green); }

/* --------------------------------------------------------- energiesaldo --- */
.saldo{ display:flex; align-items:center; justify-content:space-between;
        background:var(--leaf); border-left:5pt solid var(--green-bar);
        padding:8.4pt 13pt 8pt 45pt; height:42pt; margin:7pt 0 7pt;
        break-inside:avoid; }
.saldo .s-links{ display:flex; flex-direction:column; gap:3pt; }
.saldo .s-lbl{ font-size:8.6pt; font-weight:700; letter-spacing:.13em; text-transform:uppercase;
               color:var(--teal-deep); }
.saldo .s-duiding{ font-size:8.4pt; font-style:italic; color:var(--ink-soft); }
.saldo .s-waarde{ font-size:13pt; font-weight:700; color:var(--green); line-height:1; }
.saldo.negatief{ background:var(--sand); border-left-color:var(--rust); }
.saldo.negatief .s-lbl,.saldo.negatief .s-waarde{ color:var(--rust-deep); }
.saldo.neutraal{ background:var(--mint); border-left-color:var(--teal-rule); }
.saldo.neutraal .s-lbl,.saldo.neutraal .s-waarde{ color:var(--teal); }

/* ---------------------------------------------- energiebatterij (chips) ---
   Tien cellen, exact zoals de gouden referentie: het AANTAL gevulde cellen
   toont de omvang, de KLEUR toont de richting (geeft / neutraal / kost).     */
.batterij{ display:inline-flex; gap:1.55pt; vertical-align:middle; }
.batterij i{ display:block; width:9pt; height:8pt; background:var(--line-warm); }
.batterij.geeft i.on{ background:var(--teal); }
.batterij.kost i.on{ background:var(--rust); }
.batterij.neutraal i.on{ background:#63748a; }
.bat-wrap{ display:flex; align-items:center; gap:8pt; }
.bat-wrap .b-num{ font-size:11.5pt; font-weight:700; }
.bat-wrap.geeft .b-num{ color:var(--green); }
.bat-wrap.kost .b-num{ color:var(--rust-deep); }
.bat-wrap.neutraal .b-num{ color:var(--ink-soft); }

.eb-legenda{ background:var(--mint); border-left:2.2pt solid var(--teal-rule);
             padding:10pt 16pt; margin:10pt 0; break-inside:avoid; }
.eb-legenda .l-lbl{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
                    color:var(--teal); margin-bottom:5pt; }
.eb-legenda .eb-rij{ display:flex; align-items:center; gap:10pt; margin:4pt 0;
                     font-size:12.5pt; color:var(--ink); }

/* ------------------------------------------------------ constructtabel ---
   Gemeten op de standaardreferentie (hoofdstuk 05, Drivers):
   kolombreedtes 75,7 / 35,1 / 122,0 / 70,1 / 188,4pt op een tekstbreedte van
   491,3pt; koprij 26,0pt hoog in #1a5d59 met 8,0pt Bold wit op x kolom+9pt;
   gegevensrijen 42,0pt hoog, celtekst 9,2pt met een regelafstand van 12,4pt,
   even rijen in #fbfbf8; celinzet 9pt links, tekstbovenkant 6,6pt onder de
   rijrand.                                                                  */
.ct{ width:100%; border-collapse:collapse; margin:7pt 0 10pt; table-layout:fixed; }
.ct th{ background:var(--teal); color:#fff; font-size:8pt; font-weight:700;
        letter-spacing:.1em; text-transform:uppercase; text-align:left;
        padding:7.6pt 9pt 0; height:26pt; vertical-align:top; }
.ct td{ font-size:9.2pt; color:var(--ink); padding:6.6pt 9pt; line-height:12.4pt;
        vertical-align:top; border:0; }
.ct tbody tr{ height:42pt; }
.ct tbody tr:nth-child(even) td{ background:var(--paper); }
/* Kolombreedtes op de koprij: WeasyPrint leidt bij table-layout:fixed de
   kolombreedtes af uit de eerste rij, niet uit percentages op <col>. Gemeten
   verhouding van de vijfkolomstabel: 75,7 / 35,1 / 122,0 / 70,1 / 188,4pt op
   491,3pt tekstbreedte. */
.ct.dim th:nth-child(1){ width:15.41%; }
.ct.dim th:nth-child(2){ width:7.14%; }
.ct.dim th:nth-child(3){ width:24.83%; }
.ct.dim th:nth-child(4){ width:14.27%; }
.ct.dim th:nth-child(5){ width:38.35%; }
/* De driekolomstabel (metingen) deelt de tekstbreedte anders. */
.ct.vrij{ table-layout:auto; }
.ct.meting th:nth-child(1){ width:26%; }
.ct.meting th:nth-child(2){ width:14%; }
.ct.meting th:nth-child(3){ width:60%; }
.ct .c-naam{ font-weight:700; }
.ct .c-net{ font-size:9.2pt; font-weight:700; white-space:nowrap; }
.ct .c-net.pos{ color:var(--green); }
.ct .c-net.neg{ color:var(--rust-deep); }
.ct .c-net.nul{ color:var(--ink-soft); }
.ct .c-waarde{ font-size:7.8pt; font-weight:700; display:block; margin-top:2.9pt; }
.ct .c-waarde.pos{ color:var(--teal-deep); }
.ct .c-waarde.neg{ color:var(--rust-deep); }

/* statuspil — kleur toont de richting van de energie */
.pil{ display:inline-block; padding:3pt 9pt; font-size:7.4pt; font-weight:700;
      letter-spacing:.1em; text-transform:uppercase; color:#fff;
      background:#6a7280; white-space:nowrap; }
.pil.geeft{ background:var(--green); }
.pil.kost{ background:var(--rust); }
.pil.neutraal{ background:#6a7280; }

/* kolombreedtes van de dimensietabel, gemeten uit de gouden referentie */
.ct.dim col.k-naam{ width:136pt; }
.ct.dim col.k-net{ width:50pt; }
.ct.dim col.k-energie{ width:185pt; }
.ct.dim col.k-status{ width:96pt; }
.ct.meting col.k-naam{ width:201pt; }
.ct.meting col.k-waarde{ width:77pt; }

/* ---------------------------------------- expertise / mensgerichtheid ---- */
.orientatie{ margin:10pt 0 6pt; break-inside:avoid; }
.orientatie .subhead{ margin-top:8pt; }
.ori-row{ display:flex; align-items:flex-start; gap:10pt; padding:5pt 0;
          border-bottom:1pt solid var(--line); }
.ori-badge{ flex:0 0 40pt; text-align:center; font-size:10pt; font-weight:700;
            letter-spacing:.08em; color:#fff; background:var(--teal);
            padding:3pt 0; }
.ori-badge.h{ background:var(--green-bar); }
.ori-badge.eh{ background:var(--ochre); }
.ori-naam{ flex:0 0 150pt; font-size:12pt; font-weight:700; color:var(--ink); }
.ori-tekst{ flex:1; font-size:12pt; color:var(--ink); line-height:1.42; }
.bron-noot,.ori-noot{ font-size:10.5pt; font-style:italic; color:var(--ink-soft); margin-top:6pt; }

/* ------------------------------------------- TaPas-Beeld / congruentie ---
   Inner Why en InnerView staan in de gouden referentie NAAST elkaar, in twee
   getinte kaarten. Dat is de identiteitslaag; hij mag nooit versmelten met de
   foci-tabel van hoofdstuk 07.                                              */
.tb-paar{ display:grid; grid-template-columns:1fr 1fr; gap:16pt; margin:10pt 0; }
.tb-kaart{ padding:12pt 16pt; border-left:3pt solid var(--green-bar);
           background:var(--leaf); break-inside:avoid; }
.tb-kaart.innerview{ border-left-color:var(--rust); background:var(--sand); }
.tb-kaart .tb-lbl{ font-size:12.5pt; font-weight:700; color:var(--green);
                   margin-bottom:5pt; }
.tb-kaart.innerview .tb-lbl{ color:var(--rust-deep); }
.tb-kaart .tb-txt{ font-size:12pt; line-height:1.45; color:var(--ink); }

.cong-cel{ background:var(--mint); border-left:2.2pt solid var(--teal-rule);
           padding:11pt 16pt; margin:9pt 0; break-inside:avoid; }
.cong-cel .l-lbl{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
                  color:var(--teal); margin-bottom:5pt; }
.cong-cel .l-txt{ font-size:13.5pt; line-height:1.5; }
.cong-cel.existentieel{ background:var(--sand); border-left-color:var(--rust); }
.cong-cel.existentieel .l-lbl{ color:var(--rust-deep); }

/* ---------------------------------------------------------- talentmotor --- */
.tm-laag{ border:1pt solid var(--line); border-left:5pt solid var(--teal-rule);
          padding:11pt 16pt; margin:8pt 0; background:var(--card); break-inside:avoid; }
.tm-laag .tm-lbl{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
                  color:var(--teal); margin-bottom:6pt; }
.tm-laag .tm-items{ display:flex; flex-wrap:wrap; gap:6pt; }
.tm-laag .tm-item{ font-size:11.5pt; font-weight:500; padding:3pt 9pt; background:var(--cream);
                   border:1pt solid var(--line); }
.tm-laag .tm-item.geeft{ color:var(--green); border-color:#cfe0c4; }
.tm-laag .tm-item.kost{ color:var(--rust-deep); border-color:#e8cfc2; }
.tm-laag .tm-item.neutraal{ color:var(--ink-soft); }
.tm-route-cel{ background:var(--leaf); border-left:2.2pt solid var(--green-bar);
               padding:11pt 16pt; margin:9pt 0; break-inside:avoid; }
.tm-route-cel .l-lbl{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
                      color:var(--green); margin-bottom:5pt; }
.tm-route-cel .l-txt{ font-size:13.5pt; line-height:1.5; }

/* -------------------------------------- bronstellingen / citatenpagina --- */
.cp-intro{ font-size:12.5pt; color:var(--ink-soft); font-style:italic; margin:8pt 0 12pt; }
.cp-kolommen{ display:grid; grid-template-columns:1fr 1fr; gap:20pt; }
.cp-kolom .subhead{ margin-top:0; }
.cp-kolom.groen .subhead{ color:var(--green); }
.cp-kolom.roos .subhead{ color:var(--rust-deep); }
.cb-lijst{ margin:0; padding:0; list-style:none; }
.cb-lijst li{ font-size:12pt; line-height:1.44; color:var(--ink); padding:6pt 0 6pt 12pt;
              border-left:2pt solid var(--line); margin-bottom:5pt; }
.cp-kolom.groen .cb-lijst li{ border-left-color:var(--green-bar); background:var(--leaf); }
.cp-kolom.roos .cb-lijst li{ border-left-color:var(--rust); background:var(--sand); }
.cb-geen{ font-size:12pt; font-style:italic; color:var(--ink-soft); }
.cp-noot{ font-size:10.5pt; font-style:italic; color:var(--ink-soft); margin-top:10pt; }
.citatenblok{ margin:10pt 0; break-inside:avoid; }
.cb-intro{ font-size:12.5pt; font-style:italic; color:var(--ink-soft); margin-bottom:8pt; }

/* ------------------------------------------------------------ bronkaart --- */
.bronkaart{ border:1pt solid var(--line); border-left:5pt solid var(--teal-rule);
            padding:11pt 16pt; margin:9pt 0; break-inside:avoid; }
.bronkaart.groen{ border-left-color:var(--green-bar); }
.bronkaart.roos{ border-left-color:var(--rust); }
.bk-titel{ font-size:11pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
           color:var(--teal); margin-bottom:5pt; }
.bk-volgorde{ font-size:12.5pt; font-weight:700; color:var(--ink); margin-bottom:6pt; }
.bk-rubriek{ font-size:10.5pt; font-weight:700; letter-spacing:.13em; text-transform:uppercase;
             color:var(--ink-faint); margin:7pt 0 2pt; }
.bk-body,.bk-citaat{ font-size:12.5pt; line-height:1.46; color:var(--ink); }
.bk-citaat{ font-style:italic; }

/* ---------------------------------------------- toekomstpistes (v5.3) ---- */
.stelling{ font-size:16pt; font-style:italic; color:var(--ink-soft); line-height:1.42;
           border-left:4pt solid var(--ochre); padding:4pt 0 4pt 20pt; margin:6pt 0 16pt; }
.piste{ border:1pt solid var(--line); border-left:6.6pt solid var(--ochre);
        padding:13pt 18pt 12pt; background:var(--cream); margin:10pt 0; break-inside:avoid; }
.piste .p-kop{ font-size:18pt; font-weight:700; color:var(--teal); line-height:1.12;
               margin-bottom:8pt; }
.piste .p-kop .p-num{ color:var(--ochre); margin-right:9pt; }
.piste .p-rij{ margin:7pt 0; }
.piste .p-lbl{ font-size:10pt; font-weight:700; letter-spacing:.16em; text-transform:uppercase;
               color:var(--teal); margin-bottom:3pt; }
.piste .p-txt{ font-size:12.5pt; color:var(--ink); line-height:1.44; }
.piste .p-ontwikkel .p-lbl{ color:var(--rust-deep); }
.reflectie{ background:#eaf0ef; border-left:5.3pt solid var(--teal);
            padding:10pt 18pt; margin:8pt 0 2pt; break-inside:avoid; }
.reflectie .r-lbl{ font-size:10pt; font-weight:700; letter-spacing:.18em; text-transform:uppercase;
                   color:var(--teal); margin-bottom:4pt; }
.reflectie .r-vraag{ font-style:italic; font-size:14pt; color:var(--teal); line-height:1.36; }

/* -------------------------------------------------------- iconenrijen ---- */
.icon-row{ display:flex; gap:14pt; align-items:center; margin:10pt 0; }
.icon-row .ic{ text-align:center; width:66pt; }
.icon-row .ic img{ width:34pt; height:34pt; }
.icon-row .ic span{ display:block; font-size:9.5pt; color:var(--ink-soft); margin-top:3pt;
                    line-height:1.2; }

/* -------------------------------------------------------- placeholders --- */
.ph{ color:#9aa3ad; font-style:italic; }

/* ------------------------------------------------------------ diversen --- */
.mantra{ font-size:20pt; font-style:italic; color:var(--teal); line-height:1.4;
         border-left:4pt solid var(--ochre); padding-left:20pt; margin:20pt 0; }
.klein{ font-size:11pt; color:var(--ink-soft); line-height:1.45; }
ul.opsom{ margin:8pt 0; padding-left:18pt; }
ul.opsom li{ font-size:13pt; line-height:1.5; margin:4pt 0; }

/* ---- compact-modus: krapper ritme voor de zwaardere hoofdstukken -------
   Gebruik compact=True op chapter(...) om overloop op te lossen. Laat NOOIT
   een saldobalk, oriëntatiestrip of kanttekening weg om ruimte te maken.   */

/* ---------------------------------------------------------------- KPI ----
   Kerncijfertegels van hoofdstuk 01, 03 en 14, gemeten uit de gouden
   referentie: witte tegel met dunne rand, groot teal cijfer, klein
   gespatieerd label eronder. Een niet-numerieke waarde ('gemiddeld',
   'hoog') krijgt de okerkleur, exact zoals in de referentie.            */
.kpi-grid{ display:grid; grid-template-columns:repeat(3, 1fr); gap:10pt;
           margin:14pt 0 4pt; break-inside:avoid; }
.kpi{ border:1pt solid var(--line); border-radius:7pt; background:var(--card);
      padding:11pt 13pt 10pt; break-inside:avoid; }
.kpi .k-waarde{ font-size:21pt; font-weight:700; color:var(--teal);
                line-height:1.05; letter-spacing:-.01em; }
.kpi.kwal .k-waarde{ color:var(--ochre); }
.kpi .k-lbl{ margin-top:6pt; font-size:8.2pt; font-weight:700;
             letter-spacing:.11em; text-transform:uppercase;
             color:var(--ink-soft); line-height:1.32; }

/* ------------------------------------------------- leeswijzer (pagina 3) ---
   Gemeten: vlak x 52 -> 543,3 / y 62,0 -> 154,0; label 7,6pt Bold #1b5e5a op
   x 72 / y 70,5; broodtekst 9,6pt #4a463f, regelafstand 14,4pt, eerste regel
   y 89,1; vette accenten #23211d. */
.readbox .lab{ font-size:7.6pt; font-weight:700; color:var(--teal);
               letter-spacing:.18em; text-transform:uppercase;
               line-height:1.2; }
.readbox p{ margin:8.8pt 0 0; font-size:9.6pt; line-height:14.4pt;
            color:var(--ink-soft); }
.readbox strong{ font-weight:700; color:var(--ink); }

/* ============================================================================
   tapas_kompas.css — v8.0 componentenlaag van het T4P Business Kompas.

   Wordt NA tapas_slider.css geladen en overschrijft waar de oude waarden niet
   met de referentie overeenkwamen. Elke waarde hieronder is gemeten uit
   T4P-Business-Kompas-Marc-Debisschop-05062026 (33 p, WeasyPrint 69.0,
   md5 689d2ae6d7948007b30f8e113705eac0) en staat gedocumenteerd in
   references/v8.0-gemeten-componentgeometrie.md. Eenheid = pt.
   ========================================================================== */

:root{
  --teal-deep:#134542;
  --rust-title:#8a4424;
  --ochre-title:#8a6608;
  --tint-teal:#eef2f0;
  --tint-rust:#f5e6dd;
  --tint-leaf:#eef3ee;
  --tint-motor1:#f4eef0;
  --tint-motor2:#fbf3e2;
  --tint-motor3:#eef3e8;
  --tint-groen:#f1f5ef;
  --tint-saldo-neg:#f7ede7;
  --tint-saldo-pos:#eef3e8;
  --reflect:#eaf0ef;
}

/* voettekst van de standaard: ZONDER '· confidential' */
@page{
  @bottom-left{ content:"TaPasCity · T4P Business Profiel"; }
}

/* hoofdstukkop: gemeten afstand tot het eerste blok = 139,4 (rulebodem 102,7) */
.chap-sub{ margin:7.7pt 0 0; }
.chap-sub + *{ margin-top:2pt !important; }
.card.compact .chap-sub{ margin:1.7pt 0 0; }
.card.compact .chap-sub + *{ margin-top:4pt !important; }

/* --------------------------------------------------------------- kpis ----- */
.kpi-grid{ display:grid; grid-template-columns:auto auto auto; gap:11pt;
           margin:11pt 0 0; break-inside:avoid; }
.kpi{ border:1pt solid var(--line); border-radius:0; background:var(--paper);
      padding:10pt 12pt; }
.kpi .k-waarde{ font-size:26pt; font-weight:800; color:var(--teal);
                line-height:1.06; letter-spacing:0; }
.kpi.kwal .k-waarde{ color:var(--ochre); }
.kpi .k-lbl{ margin-top:7pt; font-size:7.4pt; font-weight:700;
             letter-spacing:.14em; text-transform:uppercase;
             color:var(--ink-faint); line-height:1.35; }

/* ---------------------------------------------------------- statement ----- */
/* Gemeten op referentiepagina 8: blok 187,8-237,4 (49,6pt bij drie regels),
   tekst op x 70,0 en doorlopend tot x 543, dus 2,2pt okeren linkerlijn,
   15,8pt binnenmarge links en geen binnenmarge rechts. */
.stelling{ font-size:var(--pt,13.5pt); font-style:italic; color:var(--teal-deep);
           line-height:1.4167; border-left:2.2pt solid var(--ochre);
           padding:2pt 0 2pt 15.8pt; margin:11pt 0 0; break-inside:avoid; }

/* ------------------------------------------------------ lagen & lijsten --- */
.laag{ background:var(--tint-teal); border-left:2.2pt solid var(--teal-rule);
       padding:10.5pt 16pt 10.4pt; margin:8pt 0 0; break-inside:avoid; }
.laag.risico{ background:var(--tint-rust); border-left-color:var(--rust); }
.laag.actie{ background:var(--tint-leaf); border-left-color:var(--green-bar); }
.laag .l-lbl{ font-size:7.4pt; font-weight:700; letter-spacing:.34em;
              text-transform:uppercase; color:var(--teal); margin-bottom:6pt; }
.laag.risico .l-lbl{ color:var(--rust); }
.laag.actie .l-lbl{ color:var(--green); }
.laag .l-txt{ font-size:var(--pt,9.6pt); line-height:1.44; color:var(--ink-soft); }
.laag .l-txt b,.laag .l-txt strong{ color:var(--ink); font-weight:700; }
.laag .l-txt i,.laag .l-txt em{ color:var(--ink-faint); }

.klijst{ margin:0; padding:0; list-style:none; }
.klijst li{ font-size:var(--pt,9.4pt); line-height:1.34; color:var(--ink-soft);
            margin:0 0 4pt; }
.klijst li:last-child{ margin-bottom:0; }
.klijst b{ color:var(--ink); font-weight:700; }

/* ------------------------------------------------------- staafmeters ------ */
.meters{ margin:10pt 0 0; break-inside:avoid; }
.meter{ display:flex; align-items:center; height:29.1pt;
        border-bottom:1pt solid var(--line); }
.meter .m-lbl{ flex:0 0 162pt; font-size:9.6pt; font-weight:600;
               color:var(--ink); }
.meter .m-bar{ flex:0 0 255.3pt; display:flex; gap:2.4pt; }
.meter .m-cel{ width:23.4pt; height:13pt; background:var(--line-warm); }
.meter .m-cel.aan{ background:var(--teal); }
.meter.kost .m-cel.aan{ background:var(--rust); }
.meter .m-wrd{ flex:1; text-align:right; font-size:9.6pt; font-weight:700;
               color:var(--teal-deep); }
.meter.kost .m-wrd{ color:var(--rust-title); }

/* ------------------------------------------------------------ tabellen ---- */
.ct{ width:100%; border-collapse:collapse; margin:7pt 0 0; }
.ct th{ background:var(--teal); color:#fff; font-size:8pt; font-weight:700;
        letter-spacing:.14em; text-transform:uppercase; text-align:left;
        padding:7.7pt 9pt; }
.ct td{ padding:6.75pt 9pt; font-size:9.2pt; color:var(--ink);
        border-bottom:1pt solid var(--line); vertical-align:middle;
        line-height:1.30; }
.ct tbody tr{ height:auto; }
.ct tbody tr:nth-child(even) td{ background:transparent; }
.ct tbody tr:nth-child(odd) td{ background:var(--paper); }
.ct .c-naam{ font-size:9.2pt; font-weight:700; }
.ct .c-naam img{ width:16pt; height:16pt; vertical-align:middle;
                 margin-right:6pt; }
.ct .c-energie{ width:122pt; }
.ct .c-net{ white-space:nowrap; }
.ct .pil{ white-space:nowrap; }
.ct .c-lezing{ color:var(--ink-soft); }
.ct .c-lezing b{ color:var(--ink); font-weight:700; }

/* energiebatterij in de tabel */
.bat{ display:flex; gap:1.55pt; }
.bat .cel{ width:9pt; height:8pt; background:var(--line-warm); }
.bat .cel.aan.geeft{ background:var(--teal); }
.bat .cel.aan.kost{ background:var(--rust); }
.bat .cel.aan.neutraal{ background:#6e6a62; }
.bat-wrd{ font-size:7.8pt; font-weight:700; margin-top:3pt; display:block; }
.bat-wrd.geeft{ color:var(--teal-deep); }
.bat-wrd.kost{ color:var(--rust-title); }
.bat-wrd.neutraal{ color:var(--ink-faint); }

.pil{ display:inline-block; padding:2.15pt 9.3pt; font-size:7.4pt;
      font-weight:700; letter-spacing:.02em; text-transform:none; color:#fff;
      background:var(--ochre); white-space:nowrap; }
.pil.geeft{ background:var(--green-bar); }
.pil.kost{ background:var(--rust); }
.pil.neutraal{ background:#b8860b; }

/* saldobalk boven een constructtabel — maten gemeten op referentiepagina 9 */
.saldo{ display:flex; align-items:center; gap:11.4pt; height:42pt;
        padding:0 16pt 0 17pt; background:var(--tint-saldo-pos);
        border:1pt solid var(--line); border-left:2.2pt solid var(--green-bar);
        margin:11pt 0 0; break-inside:avoid; color:var(--green-bar); }
.saldo.neg{ background:var(--tint-saldo-neg); border-left-color:var(--rust);
            color:var(--rust); }
.saldo.neu{ background:var(--paper); border-left-color:#6d6b61; color:#6d6b61; }
.saldo .s-txt{ display:flex; flex-direction:column; }
.saldo .s-lbl{ font-size:8.6pt; line-height:1.0; font-weight:700;
               letter-spacing:.02em; text-transform:uppercase;
               color:var(--ink-faint); margin-bottom:5.3pt; }
.saldo .s-toe{ font-size:8.4pt; line-height:1.0; font-style:italic;
               color:var(--ink-soft); }
.saldo .s-wrd{ margin-left:auto; font-size:13pt; font-weight:700;
               color:var(--green); }
.saldo.neg .s-wrd{ color:var(--rust-title); }
.saldo.neu .s-wrd{ color:#6d6b61; }

/* meting- en vrije tabel */
.ct.meting td:last-child,.ct.vrij td:last-child{ color:var(--ink); }
.tabelkop{ font-size:9.6pt; font-weight:700; color:var(--teal-deep);
           margin:11pt 0 0; }

/* ------------------------------------------------------------- subkop ----- */
.subkop{ font-size:11pt; font-weight:700; color:var(--teal-deep);
         margin:12pt 0 0; }
/* Gemeten op de referentie (p24): kaarthoogte 97,5pt bij kop + 3 regels,
   onderlinge tussenruimte 10,0pt, kop en tekst op x 70,0 (dus 18pt links). */
.tekstblok{ margin:10pt 0 0; break-inside:avoid; border:1pt solid var(--line);
            border-left:3pt solid var(--teal); background:#fcfbf8;
            padding:13.1pt 14pt 12.3pt 15pt; }
.tekstblok.tb-a2{ border-left-color:var(--neutraal); }
.tekstblok.tb-a3{ border-left-color:var(--geeft); background:#f1f5ef; }
.tekstblok .tb-kop{ font-size:var(--kop,10.5pt); font-weight:700; color:var(--teal-deep);
                    margin-bottom:3pt; }
.tekstblok.tb-a2 .tb-kop{ color:var(--neutraal); }
.tekstblok.tb-a3 .tb-kop{ color:var(--geeft); }
.tekstblok .tb-txt{ font-size:var(--pt,9.6pt); line-height:1.34; color:var(--ink-soft); }
.tekstblok .tb-txt b{ color:var(--ink); }
.alinea{ font-size:var(--pt,9.4pt); line-height:1.34; color:var(--ink-soft);
         margin:9pt 0 0; }
.alinea.intro{ font-size:12pt; font-style:italic; }
.alinea b{ color:var(--ink); font-weight:700; }
.regel{ font-size:9.6pt; color:var(--ink-soft); margin:8pt 0 0; }
.regel.conclusie{ font-size:10.5pt; font-weight:700; color:var(--teal-deep); }

/* --------------------------------------------- paar getinte tekstkaarten -- */
.paar{ display:grid; grid-template-columns:1fr 1fr; gap:6.9pt; margin:11pt 0 0; }
.paar .pk{ background:var(--paper); border:1pt solid var(--line);
           border-left:2.2pt solid var(--teal-rule);
           padding:14.4pt 6pt 1.3pt 13.8pt; break-inside:avoid; }
.paar .pk.rust{ background:var(--tint-rust); border-left-color:var(--rust); }
.paar .pk .pk-kop{ font-size:var(--kop,10.5pt); font-weight:700; color:var(--teal-deep);
                   margin-bottom:3.1pt; }
.paar .pk.rust .pk-kop{ color:var(--rust-title); }
.paar .pk .pk-txt{ font-size:var(--pt,9.4pt); line-height:1.34; color:var(--ink-soft); }

/* --------------------------------------------------------- congruentie ---- */
.cong{ background:var(--tint-teal); border-left:2.2pt solid var(--teal-rule);
       padding:10pt 16pt 12pt; margin:9pt 0 0; break-inside:avoid; }
.cong .cong-lbl{ font-size:7.4pt; font-weight:700; letter-spacing:.34em;
                 text-transform:uppercase; color:var(--teal);
                 margin-bottom:6pt; }
.cong-raster{ display:grid; grid-template-columns:1fr 1fr; gap:6pt; }
.cong-cel{ background:#fff; border:1pt solid var(--line);
           border-left:2.2pt solid var(--green-bar); padding:7pt 10pt;
           margin:0; break-inside:avoid; }
.cong-cel:nth-child(2){ border-left-color:var(--ochre); }
.cong-cel:nth-child(3){ border-left-color:var(--rust); }
.cong-cel:nth-child(4){ border-left-color:var(--teal); }
.cong-cel .cc-kop{ font-size:var(--kop,8.4pt); font-weight:700; color:var(--green);
                   margin-bottom:2pt; letter-spacing:0; text-transform:none; }
.cong-cel:nth-child(2) .cc-kop{ color:var(--ochre-title); }
.cong-cel:nth-child(3) .cc-kop{ color:var(--rust-title); }
.cong-cel:nth-child(4) .cc-kop{ color:var(--teal-deep); }
.cong-cel .cc-txt{ font-size:var(--pt,8.6pt); line-height:1.34; color:var(--ink-soft); }

/* ------------------------------------------------------ citatenkaarten ---- */
.cit2{ display:grid; grid-template-columns:1fr 1fr; gap:18pt; margin:14.7pt 0 0; }
.citk{ background:var(--paper); border:1pt solid var(--line);
       border-left:5pt solid var(--green-bar);
       padding:16.6pt 16.7pt 16.6pt 11.8pt; }
.citk.minst{ border-left-color:var(--rust); }
.citk .ck-kop{ font-size:7.6pt; font-weight:700; letter-spacing:.1em;
               text-transform:uppercase; color:var(--green);
               margin-bottom:9.5pt; }
.citk.minst .ck-kop{ color:var(--rust-title); }
.citk ul{ margin:0; padding:0; list-style:none; }
.citk li{ border:1pt solid var(--line); padding:6.4pt 0 7.1pt 16pt; margin:0 0 4pt;
          position:relative;
          font-size:var(--pt,11pt); font-style:italic; color:var(--teal-deep);
          line-height:1.42; break-inside:avoid; }
.citk li:last-child{ margin-bottom:0; }
/* Het aanhalingsteken hangt links in de kaderlijn (gemeten: glyph op x 65,8,
   tekst op x 78,8 — dus 13pt hangende indent, 12,5pt groot). */
.citk li .q{ position:absolute; left:0; top:1.6pt;
             font-size:calc(var(--pt,11pt) * 1.36);
             font-style:italic; color:var(--ochre); }

.c1-intro{ font-size:8.6pt; font-style:italic; color:var(--ink-faint);
           margin:9pt 0 0; }
.cit1{ background:var(--paper); border:1pt solid var(--line);
       padding:7pt 14pt 6pt; margin:6pt 0 0; }
.cit1 .c1-raster{ display:grid; grid-template-columns:1fr 1fr; gap:12pt; }
.cit1 .c1-kop{ font-size:7.0pt; font-weight:700; letter-spacing:.1em;
               text-transform:uppercase; color:var(--green);
               margin-bottom:6pt; }
.cit1 .c1-kol.minst .c1-kop{ color:var(--rust-title); }
.cit1 ul{ margin:0; padding:0; list-style:none; }
/* Gemeten op referentiepagina 8: regelblok 226,8 x 25,9pt met alleen een
   groene of okerrode linkerlijn, aanhalingsteken hangend op 2,4pt en tekst op
   12,2pt van de linkerlijn, regelafstand 11,4pt, tussenruimte 4,0pt. */
.cit1 li{ border-left:2.2pt solid var(--green-bar); padding:1.5pt 0 1.6pt 12.2pt;
          margin:0 0 4pt; font-size:var(--pt,9pt); font-style:italic;
          color:var(--teal-deep); line-height:1.267; position:relative;
          break-inside:avoid; }
.cit1 li:last-child{ margin-bottom:0; }
.cit1 li .q{ position:absolute; left:2.4pt; top:0;
             font-size:calc(var(--pt,9pt) * 1.22); font-style:italic;
             color:var(--ochre); }
.cit1 .c1-kol.minst li{ border-left-color:var(--rust); }

/* ---------------------------------------------------------- bronkaarten --- */
.bronkaart{ background:var(--paper); border:1pt solid var(--line);
            border-left:2.2pt solid var(--teal-rule); padding:9pt 16pt 11pt;
            margin:8pt 0 0; break-inside:avoid; }
.bronkaart.rust{ background:var(--tint-rust); border-left-color:var(--rust); }
.bronkaart.groen{ background:var(--tint-groen);
                  border-left-color:var(--green-bar); }
.bk-titel{ font-size:10.5pt; font-weight:700; letter-spacing:0;
           text-transform:none; color:var(--teal-deep); margin-bottom:3pt; }
.bronkaart.rust .bk-titel{ color:var(--rust-title); }
.bronkaart.groen .bk-titel{ color:var(--green); }
.bk-volgorde{ font-size:8.2pt; font-weight:700; letter-spacing:.06em;
              text-transform:uppercase; color:var(--ink-faint);
              margin-bottom:4pt; }
.bk-rubriek{ font-size:7pt; font-weight:700; letter-spacing:.16em;
             text-transform:uppercase; color:var(--teal); margin:6pt 0 2pt; }
.bronkaart.rust .bk-rubriek{ color:var(--rust-title); }
.bronkaart.groen .bk-rubriek{ color:var(--green); }
.bk-body{ font-size:var(--pt,10pt); line-height:1.34; color:var(--ink); }
.bk-body.citaat{ font-size:10.4pt; font-style:italic; }
.bk-body b{ font-weight:700; }

/* --------------------------------------------------------- motorpanelen --- */
.motor{ background:var(--tint-motor1); border:1pt solid var(--line);
        border-left:2.2pt solid var(--teal-rule); padding:9pt 16pt 11pt;
        margin:11pt 0 0; break-inside:avoid; }
.motor.p2{ background:var(--tint-motor2); border-left-color:var(--ochre); }
.motor.p3{ background:var(--tint-motor3); border-left-color:var(--green-bar); }
.motor .mt-kop{ font-size:12pt; font-weight:700; color:var(--teal-deep); }
.motor.p2 .mt-kop{ color:var(--rust-title); }
.motor.p3 .mt-kop{ color:var(--green); }
.motor .mt-vraag{ font-size:9.5pt; font-weight:600; font-style:italic;
                  color:var(--ink-faint); }
.motor .mt-noot{ font-size:8.4pt; font-style:italic; color:var(--ink-faint);
                 margin-top:2pt; }
.motor .mt-items{ display:flex; justify-content:space-around;
                  align-items:flex-start; margin-top:9pt; }
.motor .mt-item{ text-align:center; width:88pt; }
.motor .mt-item img{ width:26pt; height:26pt; }
.motor .mt-item .mi-naam{ display:block; font-size:8pt; font-weight:700;
                          color:var(--ink); margin:4pt 0 4pt; line-height:1.2; }

/* --------------------------------------------------------- routekaarten --- */
.routes{ display:grid; grid-template-columns:1fr 1fr 1fr; gap:8pt;
         margin:11pt 0 0; }
.route{ background:var(--paper); border:1pt solid var(--line);
        border-left:2.2pt solid var(--green-bar); padding:8pt 11pt 10pt;
        break-inside:avoid; }
.route.teal{ border-left-color:var(--teal); }
.route.rust{ border-left-color:var(--rust); }
.route .rt-lbl{ font-size:6.8pt; font-weight:700; letter-spacing:.16em;
                text-transform:uppercase; color:var(--green);
                margin-bottom:4pt; line-height:1.3; }
.route.teal .rt-lbl{ color:var(--teal-deep); }
.route.rust .rt-lbl{ color:var(--rust-title); }
.route .rt-txt{ font-size:8.4pt; line-height:1.34; color:var(--ink-soft); }

/* --------------------------------------------------------- rasterkaarten -- */
.raster{ display:grid; grid-template-columns:1fr 1fr; gap:10pt 9.9pt;
         margin:11pt 0 0; }
.rk{ background:var(--tint-groen); border:1pt solid var(--line);
     border-left:2.2pt solid var(--green-bar); padding:9pt 13pt 11pt;
     break-inside:avoid; }
.rk.oker{ background:var(--paper); border-left-color:var(--ochre); }
.rk.rust{ background:var(--tint-rust); border-left-color:var(--rust); }
.rk.teal{ background:var(--paper); border-left-color:var(--teal); }
.rk .rk-kop{ font-size:10.5pt; font-weight:700; color:var(--green);
             margin-bottom:4pt; }
.rk.oker .rk-kop{ color:var(--ochre-title); }
.rk.rust .rk-kop{ color:var(--rust-title); }
.rk.teal .rk-kop{ color:var(--teal-deep); }
.rk .rk-txt{ font-size:var(--pt,9.4pt); line-height:1.34; color:var(--ink-soft); }

/* ----------------------------------------------------------- waakpunten --- */
.waak{ background:var(--tint-rust); border-left:2.2pt solid var(--rust);
       padding:9pt 16pt 11pt; margin:8pt 0 0; break-inside:avoid; }
.waak .wk-lbl{ font-size:7.4pt; font-weight:700; letter-spacing:.34em;
               text-transform:uppercase; color:var(--rust-title);
               margin-bottom:3pt; }
.waak .wk-titel{ font-size:13pt; font-weight:700; color:var(--rust-title);
                 margin-bottom:4pt; line-height:1.18; }
.waak .wk-txt{ font-size:var(--pt,9.5pt); line-height:1.34; color:var(--ink-soft); }
.waak .wk-txt b{ color:var(--ink); }

/* --------------------------------------------------------------- pistes --- */
.piste{ background:var(--paper); border:1pt solid var(--line);
        border-left:2.2pt solid var(--ochre); padding:10pt 18pt 12pt;
        margin:8pt 0 0; break-inside:avoid; }
.piste .p-kop{ font-size:13.5pt; font-weight:800; color:var(--teal);
               line-height:1.16; margin-bottom:6pt; }
.piste .p-kop .p-num{ color:var(--ochre); margin-right:8pt; }
.piste .p-rij{ margin:6pt 0 0; }
.piste .p-lbl{ font-size:7.2pt; font-weight:700; letter-spacing:.24em;
               text-transform:uppercase; color:var(--teal); margin-bottom:2pt; }
.piste .p-txt{ font-size:var(--pt,9.4pt); line-height:1.34; color:var(--ink-soft); }
.piste .p-ontwikkel .p-lbl{ color:var(--rust-title); }
.reflectie{ background:var(--reflect); border-left:2.2pt solid var(--teal-deep);
            padding:8pt 16pt 9pt; margin:8pt 0 0; break-inside:avoid; }
.reflectie .r-lbl{ font-size:7.2pt; font-weight:700; letter-spacing:.24em;
                   text-transform:uppercase; color:var(--teal-deep);
                   margin-bottom:3pt; }
.reflectie .r-vraag{ font-size:10.6pt; font-style:italic;
                     color:var(--teal-deep); line-height:1.38; }

/* ----------------------------------------------------- batterijlegende ---- */
.eb-legenda{ display:flex; gap:18pt; align-items:center; margin:9pt 0 0;
             break-inside:avoid; }
.eb-legenda .eb-post{ display:flex; align-items:center; gap:6pt;
                      font-size:8.6pt; color:var(--ink-soft); }

/* ------------------------------------------------ oriëntatiestrip (v6.1) -- */
.orientatie{ margin:9pt 0 0; break-inside:avoid; }
.ori-row{ display:flex; align-items:flex-start; gap:9pt; padding:1.4pt 0;
          border-bottom:1pt solid var(--line); }
.ori-badge{ flex:0 0 30pt; text-align:center; font-size:7.2pt; font-weight:700;
            letter-spacing:.04em; color:#fff; background:var(--teal);
            padding:2pt 0; }
.ori-badge.h{ background:var(--green-bar); }
.ori-badge.eh{ background:var(--ochre); }
.ori-naam{ flex:0 0 118pt; font-size:8pt; font-weight:700; color:var(--ink); }
.ori-tekst{ flex:1; font-size:8pt; color:var(--ink-soft); line-height:1.34; }
.ori-noot,.bron-noot{ font-size:7pt; font-style:italic;
                      color:var(--ink-faint); margin-top:5pt; }

/* de statuspil in de talentmotor is gemeten op 7,6pt */
.motor .pil{ font-size:7.6pt; }
/* lagenblokken staan 3,5pt onder elkaar (gemeten) */
.laag + .laag{ margin-top:8pt; }

/* ---------------------------------------------- compacte hoofdstukken ------
   Gemeten uit de referentie: hoofdstukken met 9,0-9,2pt broodtekst gebruiken
   een krapper verticaal ritme (lagen, tabelrijen, citaten).             */
.card.compact .laag{ padding:4.2pt 16pt 4.2pt; margin:6.5pt 0 0; }
.card.compact .laag + .laag{ margin-top:6.5pt; }
.card.compact .laag .l-lbl{ margin-bottom:2.4pt; }
.card.compact .laag .l-txt{ line-height:1.34; }
.ct.dim td{ padding:4.0pt 9pt; }
.card.compact .ct td{ line-height:1.30; }
.chap-sub + .ct{ margin-top:14.7pt !important; }

/* -------------------------------------------------------- bolletjeslijst ---
   Gemeten uit de referentie: bolletje op x 70,0, tekst op x 85,0 —
   een hangende indent van 15pt, geen extra ruimte tussen de items.     */
.blijst{ margin:0; padding:0 0 0 15pt; list-style:disc outside; }
.blijst li{ margin:0 0 4.7pt; }

/* Eerste tekstblokkaart onder de hoofdstukondertitel: gemeten 14,7pt. */
.chap-sub + .tekstblok, .chap-sub + .ond > .tekstblok{ margin-top:14.7pt !important; }

/* Compacte hoofdstukken (gemeten op referentiepagina 17, hoofdstuk 12):
   kaarthoogte 58,8pt bij kop + 2 regels, tussenruimte 7,0pt, tekst op x 68,0. */
.card.compact .tekstblok{ padding:8.7pt 14pt 8.7pt 13pt; margin:7pt 0 0; }
.card.compact .tekstblok .tb-kop{ margin-bottom:3pt; }
.card.compact .blijst li{ margin:0 0 2pt; }

/* Kleine citaatrijm (gemeten op referentiepagina 14, 9,2pt): smallere kolomkloof,
   krappere kaart- en itempadding en een dichtere regelafstand. */
.cit2.klein{ gap:14pt; }
.cit2.klein .citk{ padding:13.6pt 13.8pt 13.8pt 8.8pt; }
.cit2.klein .ck-kop{ margin-bottom:6.5pt; }
.cit2.klein li{ padding:3.2pt 0 3.4pt 13pt; margin:0 0 3.5pt; line-height:1.30; }

/* --------------------------------------------- legenda energiebatterij -----
   Alle maten gemeten op referentiepagina 6.                                */
.bl-kaart{ background:#eef2f0; border:1pt solid var(--line);
           padding:10.3pt 13.8pt 10.8pt 13.8pt; margin:18.5pt 0 0;
           break-inside:avoid; }
.bl-titel{ font-size:7.4pt; font-weight:700; letter-spacing:.34em;
           text-transform:uppercase; color:var(--teal-deep); margin:0 0 11pt; }
.bl-rij{ display:flex; align-items:center; gap:10.4pt; margin:0 0 3.45pt; }
.bl-rij.geeft{ color:var(--geeft); }
.bl-rij.neutraal{ color:#6d6b61; }
.bl-rij.kost{ color:var(--kost); }
.bl-bat{ position:relative; display:inline-block; width:19.6pt; height:21.2pt;
         border:1.2pt solid currentColor; border-radius:2pt; background:#fff; }
.bl-bat::after{ content:""; position:absolute; left:19.6pt; top:8.4pt;
                width:1.6pt; height:3.6pt; background:currentColor; }
.bl-cellen{ position:absolute; left:2.3pt; top:4.1pt; display:flex; gap:1.1pt; }
.bl-cel{ display:inline-block; width:3.4pt; height:7pt; background:currentColor; }
.bl-txt{ font-size:8.8pt; color:var(--ink); }
.bl-noot{ font-size:8pt; color:var(--ink-soft); line-height:1.36; margin:11pt 0 0; }

/* Opsommingen binnen een laagblok: bolletje binnen de kaart, tekst op x 86
   (gemeten op referentiepagina 4). */
.laag .klijst{ margin:0; padding:0 0 0 16pt; list-style:disc outside; }
.laag .klijst li{ margin:0 0 4.4pt; }

/* De referentie laat een laagblok wel over een paginagrens breken (p5 -> p6:
   'Over de bronstellingen' loopt door). Daarom hier expliciet toegestaan. */
.laag{ break-inside:auto; }

/* De saldobalk hangt op dezelfde hoogte als de constructtabel (14,7pt onder de
   ondertitel), zodat kaart en tabel exact op de referentierasterlijn staan. */
.chap-sub + .saldo, .chap-sub + .ond > .saldo{ margin-top:14.7pt !important; }

/* Gemeten op de referentie: een tabelregel telt 12,3pt (9,2pt tekst) en de
   naamkolom heeft een ruimere regelafstand van 14,2pt; daardoor is een rij met
   tweeregelige naam 42,1pt hoog en een rij met tweeregelige lezing 38,4pt. */
.ct td{ line-height:1.337; }
.ct .c-naam{ line-height:1.545; }

/* ---- congruentiekaart, gemeten op referentiepagina 8 (382,6-557,2) -------- */
.cong{ padding:6pt 12pt 5.5pt 13.8pt; margin:9.4pt 0 0; }
.cong .cong-lbl{ letter-spacing:.34em; margin-bottom:4.4pt; }
.cong .cong-intro{ font-size:9pt; line-height:1.333; color:var(--ink-soft);
                   margin:0 0 6.2pt; }
.cong-cel{ padding:6.5pt 10pt 7pt; }
.cong-cel .cc-kop{ font-size:6.6pt; letter-spacing:.06em;
                   text-transform:uppercase; margin-bottom:4.1pt; }
.cong-cel .cc-txt{ font-size:8.3pt; line-height:1.325; }

/* ---- citatenkaart met intro binnen de kaart (referentiepagina 8) --------- */
.cit1{ padding:7.4pt 12.8pt 12.7pt; margin:5pt 0 0; }
.cit1 .c1-intro{ font-size:8pt; font-style:italic; color:var(--ink-faint);
                 line-height:1.34; margin:0 0 5.5pt; }
.cit1 .c1-kop{ letter-spacing:.16em; margin-bottom:9.1pt; }

/* ---- kaart met de letterlijke stellingen (referentiepagina 8) ------------ */
.cit1{ padding:7.4pt 12.7pt 12.7pt 12.8pt; }
.cit1 .c1-kop{ line-height:1.5; margin-bottom:4pt; }
.cit1 .c1-intro{ margin-bottom:5.5pt; }

/* Compacte hoofdstukken zetten de titelfilet 3pt hoger (gemeten: 97,7 tegen
   100,7) en houden de ondertitel op 104,4. */
.card.compact .chap-rule{ margin-top:2.9pt; }
.card.compact .chap-sub{ margin:4.7pt 0 0; }

/* Gemeten: in de referentie groeit de naamkolom mee met de langste naam
   (NET staat op 136,7 / 153,9 / 167,5 / 191,8 al naargelang de tabel), dus de
   naam breekt nooit af. */

/* De referentie gebruikt géén vaste kolompercentages voor de dimensietabellen:
   de naamkolom groeit mee met de langste naam. Daarom automatische layout, met
   enkel de energiekolom (122pt) vast. */
.ct.dim{ table-layout:fixed; }
.ct.dim th:nth-child(1),.ct.dim th:nth-child(2),.ct.dim th:nth-child(3),
.ct.dim th:nth-child(4),.ct.dim th:nth-child(5){ width:auto; }
/* De lezingkolom absorbeert alle overblijvende breedte, zodat naam-, net- en
   statuskolom exact hun inhoudsbreedte houden (zoals gemeten). */


/* Losse reflectiebalk na het afsluitende lagenblok (referentiepagina 26:
   label op 677,8 en vraag op 691,1, dus ruim los van het lagenblok). */
.reflectie.los{ margin-top:24pt; }

/* Gemeten op referentiepagina 25/26: een openingsstelling begint op y157,1
   (regelafstand 17,0pt bij 12,0pt), de pistekaarten hebben tekst op x73,0 met
   een regelafstand van 13,55pt bij 9,4pt, koppen op 15,1pt en rubriekslabels
   met een letterafstand van 0,164em. */
.chap-sub + .stelling, .chap-sub + .ond > .stelling{ margin-top:19.8pt !important; }
.piste .p-txt{ line-height:1.4415; }
.piste .p-lbl{ letter-spacing:.164em; margin-bottom:2.9pt; }
.piste .p-kop{ line-height:1.119; }
.reflectie .r-lbl{ letter-spacing:.164em; }
/* De referentie splitst de reflectiebalk van piste 2 over pagina 25/26 (label
   op 741,6, vraag op 56,0), dus binnen de balk mag afgebroken worden. */
.reflectie{ break-inside:auto; }
/* Pistekaart 2 loopt in de referentie zelf over de paginarand (kop op 548,3,
   reflectie splitst), dus ook de pistekaart mag afbreken. */
.piste{ break-inside:auto; }

/* ---- gemeten regelafstanden per lettergrootte (mediaan over de referentie):
   9,1pt -> 12,38 (1,360) · 9,4pt -> 13,35 (1,420) · 9,5pt -> 13,68 (1,440)
   9,6pt -> 14,02 (1,460) · 10,0pt -> 15,00 (1,500) · 10,4pt -> 14,56 (1,400)
   10,6pt -> 14,42 (1,360) · 12,0pt -> 17,04 (1,420). ------------------------ */
.alinea, .rk .rk-txt, .klijst li,
.tekstblok .tb-txt{ line-height:1.420; }
.card.compact .tekstblok .tb-txt{ line-height:1.360; }
.waak .wk-txt{ line-height:1.440; }
.laag .l-txt{ line-height:1.460; }
.bk-body{ line-height:1.500; }
.reflectie .r-vraag{ line-height:1.360; }
.piste .p-txt{ line-height:1.420; }
.bk-body.citaat{ line-height:1.400; }

/* Routekaarten (referentiepagina 18): label 6,8pt zonder letterafstand,
   tekst en label beide op x 63,8. */
.route .rt-lbl{ letter-spacing:0; }
.route{ padding-left:11.8pt; }

/* Gemeten op de referentie: de eerste titelregel staat op y45,2 (gelijk met de
   bovenkant van het hoofdstuknummer), de runhead is gespatieerd op 0,25em, een
   openingsalinea begint op y140,1 met regelafstand 14,1pt (1,50) en de
   motorpanelen zetten hun tekst op x73,0. */

.runhead{ letter-spacing:.25em; }
.alinea{ line-height:1.50; }
.chap-sub + .alinea, .chap-sub + .ond > .alinea{ margin-top:16.6pt !important; }
.motor{ padding-left:18.8pt; }
.route{ padding-left:9.6pt; }

/* Gemeten op de referentie: cellen van de vrije tabellen en de metingtabel
   lijnen bovenaan uit, niet gecentreerd. */
.ct.vrij td, .ct.meting td{ vertical-align:top; }

/* --- Gemeten letterafstanden en fontstijlen (breedtevergelijking per regel met
   de referentie; elke waarde volgt uit de gemeten regelbreedte). ------------- */
.motor .mt-vraag{ font-size:9.5pt; font-weight:600; font-style:italic; }
.bronkaart .bk-body{ font-style:italic; line-height:1.394; }
.bronkaart{ padding-left:16.8pt; }
.bk-rubriek{ letter-spacing:.141em; }
.laag .l-lbl, .cong .cong-lbl, .waak .wk-lbl, .bl-titel{ letter-spacing:.17em; }
.cong-cel .cc-kop{ letter-spacing:.117em; }
.piste .p-lbl, .reflectie .r-lbl{ letter-spacing:.178em; }
.citk .ck-kop{ letter-spacing:.139em; }
.ct th{ letter-spacing:.062em; }
.saldo .s-lbl{ letter-spacing:.110em; }
.runhead{ letter-spacing:.394em; }

/* Gemeten titelritme: eerste titelregel op y45,2, tweede op y76,5 (pitch 31,3pt).
   Bij een tweeregelige titel compenseert w2 de extra hoogte zodat de titelfilet
   op y115,0 blijft (eenregelig y100,7). */
.chap-title{ line-height:25pt; top:1.6pt; padding-bottom:0; }
.chap-title.w2{ margin-bottom:6.3pt; }
.card.compact .chap-title{ margin-bottom:2.9pt; }
.card.compact .chap-title.w2{ margin-bottom:6.3pt; }

/* Gemeten op referentiepagina 8: identiteitskaarten starten 32,0pt onder de
   laatste alinearegel, hun broodtekst (9,1pt) heeft een pitch van 12,35pt en de
   congruentiekaart volgt 33,2pt onder de kaarten. */
.paar{ margin-top:-1pt; }
.paar .pk .pk-txt{ line-height:1.357; }
.cong{ margin-top:12.2pt; }

/* Gemeten op referentiepagina 4: de kerncijferkaarten staan op 52–203,0 /
   214,0–381,3 / 392,3–543,3 (tussenruimte 11,0), rij 1 op y139,4–208,6, de
   waarde begint 9,1pt onder de kaartrand en de tekst op x65,8. */
.kpi-grid{ grid-template-columns:151pt 167.3pt 151pt; margin-top:36.7pt; }
.kpi{ padding:11.7pt 12pt 11.4pt 12.8pt; }
.kpi .k-lbl{ letter-spacing:.17em; }

/* De kerncijferrij is het eerste onderdeel na de cursieve ondertitel; de
   referentie zet de bovenrand op y139,4 (dus 15,0pt onder die regel). */
.chap-sub + .kpi-grid, .chap-sub + .ond > .kpi-grid{ margin-top:15pt !important; }

/* Gemeten op referentiepagina 4: de stellingkaart start 14,0pt onder de
   kerncijferrij, een tekstblok 18,2pt onder het vorige blok. */
.stelling{ margin-top:14.3pt; }
.tekstblok{ margin-top:18.2pt; }

/* Referentiepagina 4: het eerste laagblok na een stellingkaart start 8,2pt
   lager dan het standaardritme tussen twee laagblokken. */
.stelling + .laag, .stelling + .ond > .laag{ margin-top:19.2pt; }

/* Gemeten op referentiepagina 18: de naam onder het icoon staat 6,3pt onder
   de icoonrand, het energiepilletje 29,7pt onder de naam; de routelabels zijn
   ruimer gespatieerd ("WAT ONTGRENDELT DE MOTOR" = 119,4pt breed). */
.motor{ margin-top:14.5pt; }
.motor .mt-items{ margin-top:10.1pt; }
.motor .mt-item .mi-naam{ margin:4pt 0 14.8pt; height:9.6pt; }
.route .rt-lbl{ letter-spacing:.095em; }

/* Gemeten op referentiepagina's 10, 12 en 14: de citaatitems op de
   bronstellingenpagina's volgen elkaar 2,75pt dichter op. */
.cit2 .citk li{ margin:0 0 1.25pt; }

/* Gemeten op referentiepagina 21: het eerste laagblok onder de ondertitel
   start 6,8pt lager, en de waakpuntkaarten hebben ruimere binnenafstanden. */
.chap-sub + .laag, .chap-sub + .ond > .laag{ margin-top:8.8pt !important; }
.waak{ margin-top:10.6pt; }
.waak .wk-lbl{ margin-bottom:5.6pt; }
.waak .wk-titel{ margin-bottom:6.1pt; }

/* Gemeten op referentiepagina 15: de bronkaarten volgen elkaar 4,2pt ruimer
   op en de rubrieken hebben iets meer lucht. Op pagina 9 lijnen alle cellen
   van de constructtabellen bovenaan uit. */
.bronkaart{ margin-top:12.2pt; }
.bronkaart .bk-rubriek{ margin-top:6.6pt; margin-bottom:2.5pt; }
.ct td{ vertical-align:top; }
/* Referentiepagina 9: in de constructtabellen is elke rij 2,6pt hoger en
   staat de naamkolom dichter op elkaar (regelpitch 14,2pt bij 12pt). */
.ct:not(.vrij):not(.meting) td{ padding-bottom:10.8pt; }
.card.compact .ct:not(.vrij):not(.meting) td{ padding-bottom:4.8pt; }
.ct .c-naam{ line-height:1.183; }

/* ===== v8.3 — gemeten op referentiepagina 8 (hoofdstuk 04, compact) ======== */
.card.compact .chap-sub + .saldo,
.card.compact .chap-sub + .ond > .saldo{ margin-top:7.8pt !important; }
.card.compact .saldo + .stelling,
.card.compact .saldo + .ond > .stelling,
.card.compact .ond > .stelling{ margin-top:4.6pt; }
.card.compact .stelling{ line-height:1.366; }
.card.compact .paar{ margin-top:-2.2pt; }
.card.compact .cong .cong-lbl{ margin-bottom:2.9pt; }
.card.compact .cong .cong-intro{ font-style:italic; margin:0 0 5.3pt; }
.card.compact .cong-cel{ padding:6.5pt 10pt 4.8pt; }
.card.compact .cong-cel .cc-kop{ margin-bottom:1.9pt; }
.card.compact .cit1{ margin-top:0.5pt; }
.card.compact .cit1 .c1-intro{ font-style:normal; margin-bottom:3.9pt; }
.card.compact .cit1 .c1-kop{ margin-bottom:3pt; }
/* Referentiepagina 8: het intro van het congruentieblok loopt tot x498,7 en
   breekt daar af (uitgevuld); de citatenkaart heeft een ruimere tekstbreedte. */
.card.compact .cong .cong-intro{ padding-right:32.6pt; text-align:justify; }
.card.compact .cit1{ padding-left:11.8pt; padding-right:10.7pt; }
/* Fijnafstemming p8 (gemeten): paar y250,5→252,2; congruentieblok y386,5→388,6. */
.card.compact .paar{ margin-top:-0.5pt; }
.card.compact .cong{ margin-top:9.8pt; }
.card.compact .cong .cong-lbl{ margin-bottom:2.5pt; }
.card.compact .cit1{ margin-top:4.9pt; }
.card.compact .cong{ margin-top:12.6pt; }

/* ===== v8.3 — gemeten op referentiepagina 24 (tekstblokken, niet-compact) ===
   Kop eerste blok y152,5 · kop→eerste bullet 19,9pt · bulletpitch 17,35pt ·
   laatste bullet → volgende blokkop 52,9pt. */
.card:not(.compact) .chap-sub + .tekstblok,
.card:not(.compact) .chap-sub + .ond > .tekstblok{ margin-top:13.7pt !important; }
.card:not(.compact) .tekstblok .tb-kop{ margin-bottom:5.3pt; }
.card:not(.compact) .blijst li{ margin-bottom:4pt; }
.card:not(.compact) .tekstblok + .tekstblok,
.card:not(.compact) .ond:has(> .tekstblok) + .ond > .tekstblok{ margin-top:8.5pt; }
/* Referentiepagina 24: eerste laagblok start 11,3pt onder het laatste tekstblok;
   twee opeenvolgende laagblokken staan 7,2pt van elkaar. */
.card:not(.compact) .ond:has(> .tekstblok) + .ond > .laag:first-child{ margin-top:11.3pt; }
.card:not(.compact) .laag + .laag{ margin-top:7.2pt; }
/* Referentiepagina 33: alinea 13,1pt onder de mantrakaart, dankwoordblok 7,8pt
   onder die alinea. */
.card:not(.compact) .ond:has(> .stelling) + .ond > .alinea{ margin-top:13.1pt; }
.card:not(.compact) .ond:has(> .alinea) + .ond > .tekstblok{ margin-top:7.8pt; }
/* Referentiepagina 33: broodtekst zonder opsomming start 1,2pt hoger. */
.card:not(.compact) .tekstblok .tb-txt:not(:has(> ul)){ margin-top:-1.2pt; }
/* Referentiepagina 29: een tekstblok onder een tabel start 10,0pt lager. */
.card:not(.compact) table + .ond > .tekstblok,
.card:not(.compact) .ct + .tekstblok{ margin-top:10pt; }

/* ============================================================= v8.4 =======
   Gemeten correcties op de referentie (33 p, 5 juni 2026).
   Elke waarde is uitgemeten met drift.py/anker.py + boxen.py, niet geschat. */

/* p6 — legenda energiebatterij: kaart 8,8pt hoger, kop-naar-rij 4,6pt korter,
   noot 3,8pt korter. */
.bl-kaart{ margin-top:9.7pt; }
.bl-titel{ margin-bottom:6.4pt; }
.bl-noot{ margin-top:7.2pt; }

/* p7 — subkop onder de kapittelsubtitel staat 13,5pt lager in de referentie;
   de metersgroep sluit 5,1pt korter aan. */
.chap-sub + .subkop{ margin-top:16.2pt !important; }
.subkop + .meters{ margin-top:4.9pt; }

/* p27 — vrije tabel: celvoet 0,7pt korter (rijhoogtedrift). */
.subkop + .ct.vrij td{ padding-bottom:6.05pt; }

/* p4 — eerste laagblok onder een stellingblok (niet-compact) 8,2pt lager. */
.card:not(.compact) .ond:has(> .stelling) + .ond > .laag:first-child{ margin-top:16.2pt; }
.card.compact .ond:has(> .stelling) + .ond > .laag:first-child{ margin-top:9.1pt; }

/* p17 — stelling direct onder de subtitel in een compact hoofdstuk. */
.card.compact .chap-sub + .stelling,
.card.compact .chap-sub + .ond > .stelling{ margin-top:7.7pt !important; }

/* p25 — stelling onder de subtitel (niet-compact) 4,0pt hoger; eerste
   pistekaart 7,9pt lager; reflectie-naar-piste 6,2pt ruimer. */
.card:not(.compact) .chap-sub + .stelling,
.card:not(.compact) .chap-sub + .ond > .stelling{ margin-top:15.8pt !important; }
.ond:has(> .stelling) + .ond > .piste:first-child{ margin-top:15.9pt; }
.reflectie + .piste{ margin-top:21.5pt; }

/* p26 — losse reflectiebalk 3,1pt hoger. */
.reflectie.los{ margin-top:20.9pt; }

/* p20 — rasterkaarten: 6,8pt lager, tekst 2,8pt naar rechts, kop-naar-tekst
   1,3pt ruimer, rijafstand 5,2pt ruimer; laagblok erna 6,0pt lager. */
.raster{ margin-top:17.8pt; gap:15.2pt 9.9pt; }
.rk{ padding-left:15.8pt; }
.rk .rk-kop{ margin-bottom:5.3pt; }
.ond:has(> .raster) + .ond > .laag:first-child{ margin-top:14pt; }

/* p11/p13/p15 — dimensietabellen (.ct.dim), gemeten op de referentie:
   tabel 4,2pt hoger, kop-naar-eerste-rij 2,2pt korter, rijhoogte 1,4pt korter,
   naamkolom 1,0pt lager, energiewoord 2,0pt hoger. */
.card.compact .saldo + .ct.dim{ margin-top:2.8pt !important; }
.card.compact .ct.dim:not(.vrij):not(.meting) td{ padding:4.0pt 9pt 3.3pt; line-height:1.283; }
.card.compact .ct.dim tbody tr:first-child td{ padding-top:1.8pt; }
.card.compact .ct.dim .c-naam{ position:relative; top:2pt; }
.card.compact .ct.dim .c-energie .bat-wrd{ position:relative; top:-2pt; }

/* p18 — talentmotorblokken 2,8pt ruimer, ook naar de subkop erna. */
.motor + .motor{ margin-top:17.3pt; }
.motor + .subkop{ margin-top:17.3pt; }

/* p21 — eerste laagblok direct onder de kapittelsubtitel 6,0pt lager. */
.chap-sub + .laag, .chap-sub + .ond > .laag{ margin-top:14.8pt !important; }

/* p28 — tekstblok onder een vrije tabel 6,8pt lager. */
.ct.vrij + .ond > .tekstblok{ margin-top:16.8pt; }

/* p11/p13 — oriëntatiestrip, gemeten op de referentie: naam links (x65,4),
   badge gecentreerd op x189,4..219,4, tekst op x227,4; geen scheidingslijnen;
   rijafstand 14,55pt; strip 20,3pt lager. */
.orientatie{ margin-top:29.3pt; padding-left:13.4pt; }
.ori-row{ gap:8pt; padding:1.7pt 0; border-bottom:0; }
.ori-naam{ flex:0 0 116pt; }
.card.compact .ct.dim tbody tr:first-child td{ padding-top:0pt; }
.ori-badge{ line-height:1; padding:1.95pt 0; }

/* p11/p13 — kernboodschap onder de oriëntatiestrip 9,5pt lager. */
.orientatie + .ond > .laag:first-child,
.orientatie + .laag{ margin-top:22.3pt; }

/* p25/p26 — pistekaarten onderling 7,3pt ruimer (reflectie zit in de kaart). */
.piste + .piste{ margin-top:15.3pt; }
`;
